1	package zkcircuit
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sort"
10		"strings"
11		"sync"
12	)
13	
14	// on-disk layout inside the data directory:
15	//
16	//	data.json    – the committed state (JSON envelope, atomically replaced)
17	//	data.json.tmp– staging file for the next commit (rename(2) target)
18	//	lock         – flock file serializing concurrent processes
19	//
20	// The envelope carries an explicit format version: files written by an
21	// incompatible future build are refused rather than silently migrated or
22	// overwritten.
23	const (
24		dirDataFile = "data.json"
25		dirTmpFile  = "data.json.tmp"
26		dirLockFile = "lock"
27	
28		// FormatVersion is the on-disk format this build writes and accepts.
29		FormatVersion = 1
30	)
31	
32	// envelope is the persisted state container.
33	type envelope struct {
34		Format   int              `json:"format"`
35		Circuits []persistCircuit `json:"circuits"`
36		Setups   []persistSetup   `json:"setups"`
37		Jobs     []persistJob     `json:"jobs"`
38	}
39	
40	type persistCircuit struct {
41		Name          string `json:"name"`
42		Version       int    `json:"version"`
43		Constraints   int    `json:"constraints"`
44		PublicInputs  int    `json:"public_inputs"`
45		PrivateInputs int    `json:"private_inputs"`
46		Frozen        bool   `json:"frozen"`
47		Description   string `json:"description"`
48	}
49	
50	type persistSetup struct {
51		Name    string `json:"name"`
52		Version int    `json:"version"`
53	}
54	
55	type persistJob struct {
56		ID       string `json:"id"`
57		Circuit  string `json:"circuit"`
58		Version  int    `json:"version"`
59		Kind     string `json:"kind"`
60		Attempt  int    `json:"attempt"`
61		Artifact string `json:"artifact,omitempty"`
62	}
63	
64	// Store is a persistent workbench backed by one local data directory.
65	//
66	// All operations are safe for concurrent use by multiple goroutines and by
67	// several processes pointed at the same directory: an in-process mutex plus a
68	// process-shared flock serialize commits, and every commit is an atomic
69	// temp-file/fsync/rename replacement. Open the directory with Open and call
70	// Close when done.
71	type Store struct {
72		dir  string
73		mu   sync.Mutex
74		lock *os.File
75	
76		data envelope
77	}
78	
79	// Open opens (creating if needed) the workbench data in dir. If the
80	// directory does not exist it is created. Existing committed data is loaded
81	// and fully validated before Open returns; on a corrupt, truncated or
82	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
83	// leaves every file in the directory untouched.
84	func Open(dir string) (*Store, error) {
85		if dir == "" {
86			return nil, invalidf("data directory must not be empty")
87		}
88		if err := os.MkdirAll(dir, 0o755); err != nil {
89			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
90		}
91		lockPath := filepath.Join(dir, dirLockFile)
92		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
93		if err != nil {
94			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
95		}
96		// Serialize against other processes while we read / validate.
97		if err := lockExclusive(lock); err != nil {
98			lock.Close()
99			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
100		}
101	
102		s := &Store{dir: dir, lock: lock}
103		if err := s.loadLocked(); err != nil {
104			unlockLock(lock)
105			lock.Close()
106			return nil, err
107		}
108		// The lock is taken again per operation; holding it for the store's
109		// lifetime would forbid two open handles on one directory.
110		if err := unlockLock(lock); err != nil {
111			lock.Close()
112			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
113		}
114		return s, nil
115	}
116	
117	// Close releases the directory lock. It does not discard committed data.
118	func (s *Store) Close() error {
119		s.mu.Lock()
120		defer s.mu.Unlock()
121		if s.lock == nil {
122			return nil
123		}
124		var first error
125		if err := unlockLock(s.lock); err != nil {
126			first = err
127		}
128		if err := s.lock.Close(); err != nil && first == nil {
129			first = err
130		}
131		s.lock = nil
132		return first
133	}
134	
135	// Dir reports the data directory backing the store.
136	func (s *Store) Dir() string { return s.dir }
137	
138	func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
139	func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }
140	
141	// loadLocked reads and validates the committed file. Caller must hold the
142	// exclusive flock; the in-process mutex is taken by the public Open path.
143	func (s *Store) loadLocked() error {
144		raw, err := os.ReadFile(s.dataPath())
145		if errors.Is(err, os.ErrNotExist) {
146			s.data = envelope{Format: FormatVersion}
147			return nil
148		}
149		if err != nil {
150			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
151		}
152		if len(strings.TrimSpace(string(raw))) == 0 {
153			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
154		}
155	
156		var env envelope
157		if err := json.Unmarshal(raw, &env); err != nil {
158			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
159		}
160		if env.Format == 0 {
161			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
162		}
163		if env.Format != FormatVersion {
164			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
165				s.dataPath(), env.Format, FormatVersion)
166		}
167		if err := validateEnvelope(env); err != nil {
168			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
169		}
170		s.data = env
171		return nil
172	}
173	
174	// commitLocked writes the pending state atomically: temp file → fsync →
175	// rename → fsync directory. Caller must hold both the in-process mutex and
176	// the exclusive flock; all in-memory mutations must already have happened and
177	// been rule-checked, so a failure here occurs before any success is reported.
178	func (s *Store) commitLocked() error {
179		s.data.Format = FormatVersion
180		// Stable output: records are stored sorted so files are deterministic.
181		sortEnvelope(&s.data)
182	
183		payload, err := json.MarshalIndent(&s.data, "", "  ")
184		if err != nil {
185			return fmt.Errorf("cannot encode data: %w", err)
186		}
187		payload = append(payload, '\n')
188	
189		tmp := s.tmpPath()
190		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
191		if err != nil {
192			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
193		}
194		if _, err := f.Write(payload); err != nil {
195			f.Close()
196			os.Remove(tmp)
197			return fmt.Errorf("cannot write staged data: %w", err)
198		}
199		if err := f.Sync(); err != nil {
200			f.Close()
201			os.Remove(tmp)
202			return fmt.Errorf("cannot flush staged data: %w", err)
203		}
204		if err := f.Close(); err != nil {
205			os.Remove(tmp)
206			return fmt.Errorf("cannot finish staged data: %w", err)
207		}
208		if err := os.Rename(tmp, s.dataPath()); err != nil {
209			os.Remove(tmp)
210			return fmt.Errorf("cannot commit data file: %w", err)
211		}
212		if err := syncDir(s.dir); err != nil {
213			// The rename already happened; lack of dir fsync only weakens crash
214			// durability, never correctness of what is visible now.
215			return nil
216		}
217		return nil
218	}
219	
220	// withLock runs fn under the in-process mutex and an exclusive flock, then
221	// atomically commits when fn requests it. The on-disk state is re-read after
222	// acquiring the lock, so concurrent commits from another process or another
223	// handle are always observed. Operations validate before mutating; a rejected
224	// operation (commit=false or an error) writes nothing and leaves committed
225	// state unchanged.
226	func (s *Store) withLock(fn func() (commit bool, err error)) error {
227		s.mu.Lock()
228		defer s.mu.Unlock()
229		if s.lock == nil {
230			return invalidf("store is closed")
231		}
232		if err := lockExclusive(s.lock); err != nil {
233			return fmt.Errorf("cannot lock data directory: %w", err)
234		}
235		defer unlockLock(s.lock)
236	
237		if err := s.loadLocked(); err != nil {
238			return err
239		}
240		commit, err := fn()
241		if err != nil {
242			return err
243		}
244		if !commit {
245			return nil
246		}
247		return s.commitLocked()
248	}
249	
250	// withLockRead runs fn under a shared flock over freshly reloaded state.
251	func (s *Store) withLockRead(fn func() error) error {
252		s.mu.Lock()
253		defer s.mu.Unlock()
254		if s.lock == nil {
255			return invalidf("store is closed")
256		}
257		if err := lockShared(s.lock); err != nil {
258			return fmt.Errorf("cannot lock data directory: %w", err)
259		}
260		defer unlockLock(s.lock)
261		if err := s.loadLocked(); err != nil {
262			return err
263		}
264		return fn()
265	}
266	
267	func sortEnvelope(env *envelope) {
268		sort.Slice(env.Circuits, func(i, j int) bool {
269			if env.Circuits[i].Name != env.Circuits[j].Name {
270				return env.Circuits[i].Name < env.Circuits[j].Name
271			}
272			return env.Circuits[i].Version < env.Circuits[j].Version
273		})
274		sort.Slice(env.Setups, func(i, j int) bool {
275			if env.Setups[i].Name != env.Setups[j].Name {
276				return env.Setups[i].Name < env.Setups[j].Name
277			}
278			return env.Setups[i].Version < env.Setups[j].Version
279		})
280		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
281	}
282	
283	// validateEnvelope re-checks every invariant on load so a tampered or
284	// hand-edited file cannot bypass the domain rules.
285	func validateEnvelope(env envelope) error {
286		seenCircuit := make(map[[2]string]bool)
287		circuitOK := make(map[[2]string]bool)
288		for i, c := range env.Circuits {
289			key := [2]string{c.Name, itoa(c.Version)}
290			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
291				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
292			}
293			if c.Version <= 0 {
294				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
295			}
296			if seenCircuit[key] {
297				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
298			}
299			seenCircuit[key] = true
300			if c.Constraints <= 0 {
301				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
302			}
303			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
304				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
305			}
306			circuitOK[key] = true
307		}
308		seenSetup := make(map[[2]string]bool)
309		for i, p := range env.Setups {
310			key := [2]string{p.Name, itoa(p.Version)}
311			if !circuitOK[key] {
312				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
313			}
314			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
315			if c == nil || !c.Frozen {
316				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
317			}
318			if seenSetup[key] {
319				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
320			}
321			seenSetup[key] = true
322		}
323		seenJob := make(map[string]bool)
324		for i, j := range env.Jobs {
325			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
326				return fmt.Errorf("job #%d has an empty or blank id", i+1)
327			}
328			if seenJob[j.ID] {
329				return fmt.Errorf("job %q appears more than once", j.ID)
330			}
331			seenJob[j.ID] = true
332			if j.Kind != "prove" {
333				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
334			}
335			if j.Attempt <= 0 {
336				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
337			}
338			key := [2]string{j.Circuit, itoa(j.Version)}
339			if !circuitOK[key] {
340				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
341			}
342			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
343			if c == nil || !c.Frozen {
344				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
345			}
346			if !seenSetup[key] {
347				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
348			}
349		}
350		return nil
351	}
352	
353	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
354		for i := range cs {
355			if cs[i].Name == name && cs[i].Version == version {
356				return &cs[i]
357			}
358		}
359		return nil
360	}
361	
362	func itoa(v int) string { return fmt.Sprintf("%d", v) }
363

