24	// TestCorruptDataRefused: corrupt, truncated or unsupported-format files
25	// must be reported as read failures, left byte-for-byte untouched, and never
26	// treated as an empty directory or overwritten by a subsequent open.
27	func TestCorruptDataRefused(t *testing.T) {
28		// Seed a valid store first so "empty file" is a truncation case, not a
29		// never-initialized directory.
30		seed := t.TempDir()
31		s, err := Open(seed)
32		if err != nil {
33			t.Fatal(err)
34		}
35		readyCircuit(t, s, "c", 1)
36		if err := s.Close(); err != nil {
37			t.Fatal(err)
38		}
39		valid, err := readDataFile(t, seed)
40		if err != nil {
41			t.Fatal(err)
42		}
43	
44		cases := []struct {
45			name    string
46			content []byte
47		}{
48			{"garbage", []byte("this is not json at all")},
49			{"empty", []byte{}},
50			{"whitespace only", []byte("   \n\t ")},
51			{"truncated json", valid[:len(valid)/3]},
52			{"cut mid object", append(append([]byte(nil), valid[:len(valid)-80]...), []byte("\n  }")...)},
53			{"unsupported format", []byte(`{"format":999,"circuits":[],"setups":[],"jobs":[]}`)},
54			{"missing format", []byte(`{"circuits":[],"setups":[],"jobs":[]}`)},
55			{"duplicate circuit", []byte(`{"format":1,"circuits":[` +
56				`{"name":"c","version":1,"constraints":1,"public_inputs":0,"private_inputs":0,"frozen":true,"description":"d"},` +
57				`{"name":"c","version":1,"constraints":2,"public_inputs":0,"private_inputs":0,"frozen":true,"description":"d"}` +
58				`],"setups":[],"jobs":[]}`)},
59			{"setup on unknown circuit", []byte(`{"format":1,"circuits":[],"setups":[{"name":"c","version":1}],"jobs":[]}`)},
60			{"setup not frozen", []byte(`{"format":1,"circuits":[` +
61				`{"name":"c","version":1,"constraints":1,"public_inputs":0,"private_inputs":0,"frozen":false,"description":"d"}` +
62				`],"setups":[{"name":"c","version":1}],"jobs":[]}`)},
63			{"job without setup", []byte(`{"format":1,"circuits":[` +
64				`{"name":"c","version":1,"constraints":1,"public_inputs":0,"private_inputs":0,"frozen":true,"description":"d"}` +
65				`],"setups":[],"jobs":[{"id":"j","circuit":"c","version":1,"kind":"prove","attempt":1}]}`)},
66			{"duplicate job", []byte(`{"format":1,"circuits":[` +
67				`{"name":"c","version":1,"constraints":1,"public_inputs":0,"private_inputs":0,"frozen":true,"description":"d"}` +
68				`],"setups":[{"name":"c","version":1}],"jobs":[` +
69				`{"id":"j","circuit":"c","version":1,"kind":"prove","attempt":1},` +
70				`{"id":"j","circuit":"c","version":1,"kind":"prove","attempt":1}]}`)},
71			{"bad counts", []byte(`{"format":1,"circuits":[` +
72				`{"name":"c","version":1,"constraints":0,"public_inputs":0,"private_inputs":0,"frozen":false,"description":"d"}` +
73				`],"setups":[],"jobs":[]}`)},
74		}
75		for _, tc := range cases {
76			t.Run(tc.name, func(t *testing.T) {
