309	// safeBuffer is a bytes.Buffer safe for the os/exec writer goroutine and the
310	// test goroutine to touch concurrently.
311	type safeBuffer struct {
312		mu  sync.Mutex
313		buf bytes.Buffer
314	}
315	
316	func (b *safeBuffer) Write(p []byte) (int, error) {
317		b.mu.Lock()
318		defer b.mu.Unlock()
319		return b.buf.Write(p)
320	}
321	
322	func (b *safeBuffer) Len() int {
323		b.mu.Lock()
324		defer b.mu.Unlock()
325		return b.buf.Len()
326	}
327	
328	func (b *safeBuffer) Bytes() []byte {
329		b.mu.Lock()
330		defer b.mu.Unlock()
331		return b.buf.Bytes()
332	}
333	
334	func (b *safeBuffer) String() string {
335		b.mu.Lock()
336		defer b.mu.Unlock()
337		return b.buf.String()
338	}
339	
340	type helperProc struct {
341		cmd *exec.Cmd
342		out *safeBuffer
343		err *safeBuffer
344	}
345	
346	func startHelper(t *testing.T, dir, mode string, extra ...string) *helperProc {
347		t.Helper()
348		cmd := exec.Command(os.Args[0], "-test.run=TestHelperProcess")
349		cmd.Env = append(os.Environ(),
350			"ZKCIRCUIT_HELPER="+mode,
351			"ZKCIRCUIT_DIR="+dir,
352		)
353		cmd.Env = append(cmd.Env, extra...)
354		h := &helperProc{cmd: cmd, out: &safeBuffer{}, err: &safeBuffer{}}
355		cmd.Stdout = h.out
356		cmd.Stderr = h.err
357		if err := cmd.Start(); err != nil {
358			t.Fatalf("start helper: %v", err)
359		}
360		return h
361	}
362	
363	func (h *helperProc) wait(t *testing.T) []ack {
364		t.Helper()
365		if err := h.cmd.Wait(); err != nil {
366			t.Fatalf("helper exited: %v\nstderr:\n%s", err, h.err.String())
367		}
368		return parseAcks(t, h.out.Bytes())
369	}
370	
371	type ack struct {
372		kind string
373		args string
374	}
375	
376	func parseAcks(t *testing.T, raw []byte) []ack {
377		t.Helper()
378		var acks []ack
379		for _, line := range strings.Split(strings.TrimSpace(string(raw)), "\n") {
380			if line == "" {
381				continue
382			}
383			if !strings.HasPrefix(line, "ACK ") {
384				t.Fatalf("unexpected helper output: %q", line)
385			}
386			rest := strings.TrimPrefix(line, "ACK ")
387			parts := strings.SplitN(rest, " ", 2)
388			acks = append(acks, ack{kind: parts[0], args: parts[1]})
389		}
390		return acks
391	}
