393	// parseAcksLenient is used on output of SIGKILLed processes: a final line
394	// could in principle be cut mid-write, so incomplete last lines are ignored
395	// rather than fatal.
396	func parseAcksLenient(t *testing.T, raw []byte) []ack {
397		t.Helper()
398		var acks []ack
399		for _, line := range strings.Split(string(raw), "\n") {
400			if !strings.HasPrefix(line, "ACK ") {
401				continue
402			}
403			rest := strings.TrimPrefix(line, "ACK ")
404			parts := strings.SplitN(rest, " ", 2)
405			if len(parts) != 2 {
406				continue
407			}
408			acks = append(acks, ack{kind: parts[0], args: parts[1]})
409		}
410		return acks
411	}
