	Modulus     *string           `json:"modulus"`
	Constraints *[]constraintFile `json:"constraints"`
}

type constraintFile struct {
	A *[]termFile `json:"a"`
	B *[]termFile `json:"b"`
	C *[]termFile `json:"c"`
}

type termFile struct {
	Wire  *int    `json:"wire"`
	Coeff *string `json:"coeff"`
}

